import re

def norm(recs):
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    return [{k: r.get(k, '') for k in keys} for r in recs]

def parse(lines):
    ports = []
    pl = []
    vlans = []
    vl = []
    skip = []
    cur = None
    sec = 'ports'
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            cur = None
            continue
        if re.match(r'^\S+@\S+.*%', s) or re.match(r'^[=-]+$', s):
            skip.append(i)
            continue
        if s.startswith('VLAN Configurations'):
            sec = 'vlan'
            cur = None
            skip.append(i)
            continue
        m = re.match(r'^([^:]+?):\s*(.*)$', s)
        if not m:
            continue
        k, v = m.group(1).strip(), m.group(2).strip()
        if k == 'Hardware Port':
            sec = 'ports'
        if sec == 'ports':
            if k == 'Hardware Port' or cur is None:
                cur = {}
                ports.append(cur)
            cur[k] = v
            pl.append(i)
        else:
            if k == 'VLAN User Defined Name' or cur is None:
                cur = {}
                vlans.append(cur)
            cur[k] = v
            vl.append(i)
    blocks = []
    if ports:
        blocks.append({'name': 'hardware_ports', 'kind': 'table', 'lines': pl, 'records': norm(ports)})
    if vlans:
        blocks.append({'name': 'vlan_configurations', 'kind': 'table', 'lines': vl, 'records': norm(vlans)})
    return {'blocks': blocks, 'skip': skip}
